CREATE POLICY "Approved editors can update draft project tasks" ON public.tasks FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM public.user_profiles u WHERE u.id = (SELECT auth.uid()) AND u.is_approved AND (u.is_admin OR u.role = 'support')) AND EXISTS (SELECT 1 FROM public.projects p WHERE p.id = tasks.project_id AND p.deleted_at IS NULL AND p.workflow_status IN ('draft','rejected'))) WITH CHECK (EXISTS (SELECT 1 FROM public.user_profiles u WHERE u.id = (SELECT auth.uid()) AND u.is_approved AND (u.is_admin OR u.role = 'support')) AND EXISTS (SELECT 1 FROM public.projects p WHERE p.id = tasks.project_id AND p.deleted_at IS NULL AND p.workflow_status IN ('draft','rejected')));;
